// Валидация + нормализация формы. Поддерживает оба тарифа: free и premium.
const input = $input.first().json;
const body = input.body || input;

const {
  tier = 'free',
  city = 'krym',
  days = 7,
  composition = 'couple',
  transport = 'car',
  budget = 5000,
  topic = 'obzor',
  notes = '',
  email = '',
  // premium-only поля (для free игнорируются)
  comfort = '',
  allergies = '',
  arrivalDate = '',
  departureDate = '',
  arrivalPoint = ''
} = body;

if (!email || !String(email).includes('@')) {
  throw new Error('Невалидный email: ' + email);
}

const tierNorm = tier === 'premium' ? 'premium' : 'free';
const nDays = Math.max(1, Math.min(21, Number(days) || 7));

const cityNames = {
  krym: 'Весь Крым',
  yalta: 'Ялта и Южный берег Крыма',
  sevastopol: 'Севастополь',
  bahchisaray: 'Бахчисарай',
  feodosiya: 'Феодосия и Коктебель',
  evpatoriya: 'Евпатория и западный Крым'
};
const compNames = {
  couple: 'пара',
  'family-kids': 'семья с детьми',
  friends: 'друзья',
  solo: 'один',
  parents: 'с родителями'
};
const transportNames = {
  car: 'на автомобиле',
  public: 'общественный транспорт (троллейбус №52, маршрутки, автобусы)',
  taxi: 'такси и трансферы',
  mixed: 'комбинированно (поезд/самолёт + такси)'
};
const topicNames = {
  obzor: 'обзорный — главные места',
  'more-plyazh': 'море и пляжи',
  gory: 'горы и треккинг',
  istoriya: 'история и архитектура',
  gastro: 'гастро и виноделие',
  's-detmi': 'с детьми',
  aktiv: 'активный отдых'
};
const comfortNames = {
  hostel: 'хостел / гестхаус',
  econom: 'эконом 3*',
  comfort: 'комфорт 4*',
  premium: 'премиум 5*+ / бутик'
};
const arrivalPointNames = {
  simferopol: 'аэропорт Симферополь',
  anapa: 'аэропорт Анапа',
  krasnodar: 'аэропорт Краснодар',
  'own-car': 'на машине через Крымский мост',
  train: 'поезд (Симферополь / Севастополь)'
};
const budgetNum = Number(budget) || 5000;
let budgetText;
if (budgetNum < 1500) budgetText = 'бюджетный (до 1 500 ₽ на чел/день)';
else if (budgetNum < 3000) budgetText = 'эконом (1 500–3 000 ₽ на чел/день)';
else if (budgetNum < 5000) budgetText = 'средний (3 000–5 000 ₽ на чел/день)';
else if (budgetNum < 10000) budgetText = 'комфорт (5 000–10 000 ₽ на чел/день)';
else budgetText = 'премиум (от 10 000 ₽ на чел/день)';

return [{
  json: {
    tier: tierNorm,
    city: String(city),
    cityName: cityNames[city] || cityNames.krym,
    days: nDays,
    composition: String(composition),
    compName: compNames[composition] || 'пара',
    transport: String(transport),
    transportName: transportNames[transport] || transportNames.car,
    budget: budgetNum,
    budgetText,
    topic: String(topic),
    topicName: topicNames[topic] || topicNames.obzor,
    notes: String(notes).slice(0, 500),
    email: String(email).trim().toLowerCase(),
    // premium-only
    comfort: tierNorm === 'premium' ? String(comfort) : '',
    comfortName: tierNorm === 'premium' ? (comfortNames[comfort] || '') : '',
    allergies: tierNorm === 'premium' ? String(allergies).slice(0, 300) : '',
    arrivalDate: tierNorm === 'premium' ? String(arrivalDate) : '',
    departureDate: tierNorm === 'premium' ? String(departureDate) : '',
    arrivalPoint: tierNorm === 'premium' ? String(arrivalPoint) : '',
    arrivalPointName: tierNorm === 'premium' ? (arrivalPointNames[arrivalPoint] || '') : ''
  }
}];

// Tier-aware промпт для OpenAI. Использует каталог проверенных мест + транспорта.
// Для free — компактный; для premium — расширенный с адресами, ресторанами, чек-листом и планом Б.
const m = $('Validate & Normalize').first().json;

// HTTP Request v4.2 в n8n превращает JSON-массив из тела ответа в отдельные
// n8n-items (по одной строке массива на item). Поэтому .first().json даёт
// только первый элемент массива, а не весь массив, и каталоги «теряются».
// Берём ВСЕ items и нормализуем — это покрывает оба варианта поведения n8n:
// (а) каталог пришёл одним item'ом с json=Array, (б) каталог разбит на N items.
function readCatalog(nodeName) {
  const items = $(nodeName).all();
  if (!items || items.length === 0) return [];
  if (items.length === 1) {
    const v = items[0].json;
    if (Array.isArray(v)) return v;
    if (v && Array.isArray(v.data)) return v.data;
    if (v && Array.isArray(v.items)) return v.items;
    return [v];
  }
  return items.map((it) => it.json);
}

const catalogArr = readCatalog('Fetch Attractions Catalog');
const transportArr = readCatalog('Fetch Transport Catalog');
const foodArr = readCatalog('Fetch Food Catalog');

// DEBUG: посчитаем размеры каталогов. Если в email видишь «каталоги пусты» —
// проверь в Executions: эта нода должна логировать catalogArr/transportArr/foodArr
// длиной >0. Если 0 — значит HTTP Request фейлится или /data/*.json вернул не JSON.
console.log('catalog sizes:',
  catalogArr.length, 'attractions,',
  transportArr.length, 'transport,',
  foodArr.length, 'food');

// Фильтр по региону: пользователь выбирает город — берём места только из соответствующего региона.
const cityToRegions = {
  krym: null,
  yalta: ['Южный берег'],
  sevastopol: ['Севастополь', 'Южный берег'],
  bahchisaray: ['Центральный Крым', 'Севастополь'],
  feodosiya: ['Восточный Крым'],
  evpatoriya: ['Западный Крым']
};
const allowedRegions = cityToRegions[m.city];
let filtered = allowedRegions ? catalogArr.filter(p => allowedRegions.includes(p.region)) : catalogArr;

if (filtered.length < 10 && allowedRegions) {
  const obyazatelno = catalogArr.filter(p => p.tags && p.tags.includes('обязательно') && !filtered.includes(p));
  filtered = filtered.concat(obyazatelno.slice(0, 8));
}

const topicTags = {
  'more-plyazh': ['море', 'пляж'],
  'gory': ['трекинг', 'горы', 'природа'],
  'istoriya': ['история', 'архитектура', 'археология'],
  'gastro': ['вино', 'винодельня'],
  's-detmi': ['с детьми'],
  'aktiv': ['активные', 'трекинг', 'адреналин']
};
const preferredTags = topicTags[m.topic] || [];

filtered.sort((a, b) => {
  const aTags = a.tags || [];
  const bTags = b.tags || [];
  const aPref = preferredTags.some(t => aTags.includes(t)) ? 1 : 0;
  const bPref = preferredTags.some(t => bTags.includes(t)) ? 1 : 0;
  if (aPref !== bPref) return bPref - aPref;
  const aMust = aTags.includes('обязательно') ? 1 : 0;
  const bMust = bTags.includes('обязательно') ? 1 : 0;
  return bMust - aMust;
});

// Каталог мест
const catalogText = filtered.map((p, i) => {
  const parts = [`${i+1}. ${p.name} — ${p.city}`];
  if (p.address) parts.push(`адрес: ${p.address}`);
  if (p.hours && p.hours.length < 80) parts.push(`часы: ${p.hours}`);
  else if (p.hours) parts.push(`часы: ${p.hours.split(',')[0]}`);
  if (p.price_avg) parts.push(`цена: ${p.price_avg}`);
  if (p.duration_min) parts.push(`длит: ${p.duration_min} мин`);
  const flagBits = [];
  if (p.rainy_ok) flagBits.push('в дождь ОК');
  if (p.kid_friendly) flagBits.push('с детьми ОК');
  if (flagBits.length) parts.push(flagBits.join(', '));
  const tagStr = (p.tags || []).filter(t => t !== 'обязательно' && t !== 'бесплатно').slice(0, 4).join(', ');
  if (tagStr) parts.push(`теги: ${tagStr}`);
  return parts.join(' | ') + (p.description ? `\n   ${p.description}` : '');
}).join('\n');

// Фильтр транспорта по выбранному способу и связанным городам региона
// transportMode из формы: car|public|taxi|mixed
const transportModeMap = {
  car: ['car_rental', 'fuel', 'road', 'bridge_info', 'airport', 'cable_car', 'boat_tour', 'walking'],
  public: ['train_long_distance', 'suburban_train', 'trolleybus', 'intercity_bus', 'marshrutka', 'airport_bus', 'city_transport', 'cable_car', 'boat_tour', 'walking', 'transport_hub'],
  taxi: ['taxi', 'transfer', 'cable_car', 'boat_tour', 'walking', 'airport'],
  mixed: ['train_long_distance', 'suburban_train', 'trolleybus', 'intercity_bus', 'marshrutka', 'taxi', 'transfer', 'airport_bus', 'cable_car', 'boat_tour', 'walking', 'transport_hub', 'airport', 'car_rental', 'bridge_info']
};
const allowedTransportTypes = transportModeMap[m.transport] || transportModeMap.mixed;

// Из транспортного каталога берём только релевантные типы и относящиеся к городам региона
const regionCities = new Set();
filtered.forEach(p => {
  if (p.city) {
    // Город из карточки может быть "Ялта" или "Гаспра, Большая Ялта" — берём первое слово
    const mainCity = p.city.split(',')[0].trim();
    regionCities.add(mainCity);
  }
});
// Также добавляем главные точки прибытия в зависимости от city
const baseCities = {
  krym: ['Симферополь', 'Севастополь', 'Ялта', 'Феодосия', 'Евпатория', 'Керчь'],
  yalta: ['Симферополь', 'Ялта', 'Алушта', 'Алупка', 'Гурзуф', 'Форос'],
  sevastopol: ['Симферополь', 'Севастополь', 'Балаклава', 'Бахчисарай'],
  bahchisaray: ['Симферополь', 'Бахчисарай', 'Севастополь'],
  feodosiya: ['Симферополь', 'Феодосия', 'Коктебель', 'Судак', 'Новый Свет', 'Керчь'],
  evpatoriya: ['Симферополь', 'Евпатория', 'Саки']
};
(baseCities[m.city] || []).forEach(c => regionCities.add(c));

let transportFiltered = transportArr.filter(t => {
  if (t.currently_operational === false) return false; // skip non-operational (закрытые аэропорты и т.п.)
  if (!allowedTransportTypes.includes(t.type)) return false;
  // Глобальные опции (без cities — пропускаем)
  if (!t.cities || !t.cities.length) return true;
  // Опция относится к региону если хотя бы один город пересекается
  return t.cities.some(c => regionCities.has(c) || c === 'весь Крым');
});

// Если осталось <8 опций — добавим базовые глобальные (Крымский мост, авиа, бензин)
if (transportFiltered.length < 8) {
  const globals = transportArr.filter(t => 
    ['bridge_info', 'airport', 'fuel', 'city_transport'].includes(t.type) && 
    !transportFiltered.includes(t)
  );
  transportFiltered = transportFiltered.concat(globals);
}

// Лимитируем до 40 опций чтобы не перегружать промпт
transportFiltered = transportFiltered.slice(0, 40);

// Текст транспортного каталога
const transportText = transportFiltered.map((t, i) => {
  const parts = [`${i+1}. ${t.name}`];
  if (t.from && t.to && t.from !== '—') parts.push(`маршрут: ${t.from} → ${t.to}`);
  if (t.operator && t.operator !== '—') parts.push(`перевозчик: ${t.operator}`);
  if (t.frequency) parts.push(`частота: ${t.frequency}`);
  if (t.duration_text) parts.push(`в пути: ${t.duration_text}`);
  if (t.price_avg) parts.push(`цена: ${t.price_avg}`);
  if (t.distance_km) parts.push(`${t.distance_km} км`);
  return parts.join(' | ') + (t.description ? `\n   ${t.description}` : '') + (t.notes ? `\n   ⚠ ${t.notes}` : '');
}).join('\n');

// Фильтр каталога еды по региону и составу
let foodFiltered = allowedRegions ? foodArr.filter(p => allowedRegions.includes(p.region)) : foodArr;
if (m.composition === 'family-kids') {
  foodFiltered = foodFiltered.sort((a, b) => (b.kid_friendly ? 1 : 0) - (a.kid_friendly ? 1 : 0));
}
if (m.topic === 'gastro') {
  // выводим винодельни и видовые в приоритет
  foodFiltered.sort((a, b) => {
    const aw = a.type === 'winery_tasting' ? 1 : 0;
    const bw = b.type === 'winery_tasting' ? 1 : 0;
    return bw - aw;
  });
}
// Премиум получает топ-30, free — топ-15
const foodLimit = m.tier === 'premium' ? 30 : 15;
const foodSlice = foodFiltered.slice(0, foodLimit);

const foodText = foodSlice.map((f, i) => {
  const parts = [`${i+1}. ${f.name} — ${f.city} (${f.type})`];
  if (f.address) parts.push(`адрес: ${f.address}`);
  if (f.hours) parts.push(`часы: ${f.hours}`);
  if (f.cuisine) parts.push(`кухня: ${f.cuisine}`);
  if (f.avg_check) parts.push(`чек: ${f.avg_check}`);
  const flagBits = [];
  if (f.kid_friendly) flagBits.push('с детьми ОК');
  if (f.vegetarian_ok) flagBits.push('вег ОК');
  if (f.view_sea) flagBits.push('вид на море');
  if (flagBits.length) parts.push(flagBits.join(', '));
  return parts.join(' | ') + (f.description ? `\n   ${f.description}` : '');
}).join('\n');

const baseHeader = `Составь маршрут по Крыму на ${m.days} дней.\n\n**Параметры**:\n- Регион: ${m.cityName}\n- Длительность: ${m.days} дней\n- Состав: ${m.compName}\n- Транспорт: ${m.transportName}\n- Бюджет: ${m.budgetText}\n- Главный интерес: ${m.topicName}\n- Особые пожелания: ${m.notes || 'нет'}`;

const catalogInstruction = `\n\n**Каталог проверенных достопримечательностей (${filtered.length} точек) — используй ТОЛЬКО их**:\n${catalogText}\n\n**Каталог проверенного транспорта (${transportFiltered.length} опций) — используй ТОЛЬКО его для перемещений**:\n${transportText}\n\n**Каталог проверенных ресторанов/кафе/столовых/виноделен (${foodSlice.length} мест) — используй ТОЛЬКО их для рекомендаций по еде**:\n${foodText}\n\n**ВАЖНО**: НЕ ВЫДУМЫВАЙ новых мест, ресторанов, кафе, адресов или способов передвижения. Все точки маршрута — из каталога достопримечательностей. Все рестораны/кафе/завтраки/обеды/ужины — ТОЛЬКО из каталога еды (используй название и адрес ТОЧНО как в каталоге). Транспорт между точками — ТОЛЬКО из каталога транспорта. Не упоминай ресторан, который не в списке.\n\n**КРИТИЧНО ПРО АЭРОПОРТЫ**: Аэропорты Симферополь и Анапа ЗАКРЫТЫ для гражданских рейсов с февраля 2022 года. НЕ ПРЕДЛАГАЙ прилёт самолётом в Крым. Единственные способы добраться в Крым из России: поезд «Таврия» (Москва/СПб/Ростов → Симферополь/Севастополь/Феодосия/Евпатория), автомобиль через Крымский мост, или прилёт в действующие аэропорты юга (Сочи, Минеральные Воды) + наземный транспорт.`;

let userPrompt;
let systemPrompt;
let maxTokens;

if (m.tier === 'premium') {
  const premiumExtras = [
    m.comfortName ? `- Уровень проживания: ${m.comfortName}` : null,
    m.arrivalPointName ? `- Прибытие через: ${m.arrivalPointName}` : null,
    m.arrivalDate ? `- Дата прибытия: ${m.arrivalDate}` : null,
    m.departureDate ? `- Дата отъезда: ${m.departureDate}` : null,
    m.allergies ? `- Аллергии и ограничения: ${m.allergies}` : null
  ].filter(Boolean).join('\n');

  const itemsPerDay = m.composition === 'family-kids' ? '5-6' : '6-8';

  userPrompt = `${baseHeader}\n${premiumExtras ? '\n**Дополнительно (премиум)**:\n' + premiumExtras + '\n' : ''}${catalogInstruction}\n\n**Премиум-требования к качеству плана**:\n1. Каждый день — ${itemsPerDay} точек с ТОЧНЫМИ временами (09:00, 11:30, 13:30, 16:00, 18:30, 20:30 — выбирай реалистичные слоты под локальный ритм: на ЮБК утро — лучшее время на дворцы и пешие тропы, после 16:00 уходи на пляж; в Севастополе — наоборот, утро на музеи в центре, вечер на Балаклаву).\n2. У КАЖДОЙ точки укажи: адрес из каталога, время в пути от предыдущей точки С НАЗВАНИЕМ конкретной транспортной опции из каталога транспорта, где парковаться (если на машине) или как добраться (если public/taxi).\n3. Для КАЖДОЙ точки — поле \"peak_window\" с указанием когда там толпы (например, \"в августе с 11:00 до 14:00 толпа автобусных групп — приезжай к открытию или после 16:00\") и \"local_tip\" с инсайдерским советом, который не написан в путеводителях.\n4. Минимум 2 заведения из каталога еды в день с полем \"what_to_order\" — КОНКРЕТНОЕ БЛЮДО (например, \"чебуреки с бараниной в Мусафире\", \"янтык по-карасубазарски в Караман\", \"дегустация сета Эссе из 6 вин\"). Не пиши \"попробуйте местную кухню\".\n5. План Б на дождливый день (rainy_alternative) — конкретные места из каталога с rainy_ok=true для этого региона, не абстрактное \"посмотрите музей\".\n6. Чек-лист на день (day_checklist): 3–5 пунктов под конкретный день (например, \"кеды с цепким протектором — на Ай-Петри спуск по сыпучке\", \"налички 500 ₽ — троллейбус №52 принимает не везде\").\n7. Поле \"cost_breakdown_rub\" в каждом дне: входы + еда + транспорт = итого (числа, конкретно).\n8. Поле \"avoid_today\" — 1–2 предупреждения чего НЕ делать в этот день (например, \"не лезь на Ай-Петри по канатке после 12:00 в выходные — час в очереди\", \"не паркуйся у Воронцовского с центрального входа — штраф, парковка с обратной стороны бесплатно\").\n9. Маршрут должен быть кольцевой/логичный: не возвращайся в одну точку дважды, не делай 200 км в день туда-обратно.\n10. Общий чек-лист поездки (checklist): 6–10 пунктов с учётом сезона если знаешь даты.\n11. Общий budget_estimate_rub: реальная цифра на ${m.compName} (${m.days} дней), не диапазон \"от и до\".\n\nВерни строго JSON по схеме (никакой markdown-обёртки):\n{\n  \"title\": \"Краткое название маршрута, конкретное\",\n  \"summary\": \"2-3 предложения с фишкой маршрута\",\n  \"days\": [\n    {\n      \"day\": 1,\n      \"title\": \"Город/тема дня\",\n      \"city\": \"Основной город\",\n      \"morning_strategy\": \"почему именно эти точки утром (1-2 предложения)\",\n      \"items\": [\n        { \"time\": \"09:00\", \"place\": \"Название из каталога\", \"address\": \"адрес из каталога\", \"travel\": \"15 мин на машине от предыдущей точки + парковка на ул. Х (или название транспортной опции из каталога с ценой)\", \"peak_window\": \"когда толпа и как её избежать\", \"local_tip\": \"инсайдерский совет\", \"note\": \"что именно посмотреть/сделать в этой точке\" }\n      ],\n      \"restaurants\": [\n        { \"name\": \"Название из каталога еды\", \"address\": \"адрес из каталога\", \"what_to_order\": \"конкретное блюдо\", \"avg_check_rub\": 1500, \"why\": \"почему именно это место именно сейчас\" }\n      ],\n      \"rainy_alternative\": \"конкретные точки из каталога с rainy_ok=true\",\n      \"day_checklist\": [\"пункт 1 под этот день\", \"пункт 2\"],\n      \"avoid_today\": [\"предупреждение 1\", \"предупреждение 2\"],\n      \"cost_breakdown_rub\": { \"entries\": 1200, \"food\": 3500, \"transport\": 800, \"total\": 5500 }\n    }\n  ],\n  \"tips\": [\"общий совет 1 (конкретный, не банальный)\", \"общий совет 2\"],\n  \"checklist\": [\"что взять с собой 1\", \"...\"],\n  \"budget_estimate_rub\": 45000\n}`;

  systemPrompt = `Ты — опытный гид по Крыму, который десять лет водит группы по Южному берегу, Севастополю, горному Крыму и Бахчисараю. Ты знаешь, где толпа в августе, какие чебуреки самые свежие в Мусафире и почему на Ай-Петри после 12:00 в выходные час очереди на канатку. Составляешь практичные маршруты с конкретными блюдами, временем толп, парковками и предупреждениями "не делай этого". ЖЁСТКОЕ ПРАВИЛО: используй ТОЛЬКО места из каталога достопримечательностей, ТОЛЬКО заведения из каталога еды, ТОЛЬКО опции из каталога транспорта — точно с их названиями, адресами и ценами. Никаких выдуманных адресов, цен, маршруток или ресторанов. Если в каталоге не хватает мест на день — лучше предложи 4 точки, чем выдумывай пятую. Каждый день должен быть ИНТЕРЕСНЫМ: пиши почему именно эта последовательность, что делать в каждой точке, какое блюдо заказать в каждом ресторане, чего избегать. Не пиши воду типа "насладитесь видами" — пиши конкретику: "на смотровой Шан-Кая лучший вид на Ай-Петри после дождя, паркуйся у поворота, не доезжая 200 м, дальше пешком". Отвечай ТОЛЬКО валидным JSON без markdown-обёртки, без комментариев.`;

  maxTokens = 6500;
} else {
  const itemsPerDay = m.composition === 'family-kids' ? '4-5' : '4-6';

  userPrompt = `${baseHeader}${catalogInstruction}\n\n**Требования**:\n1. Каждый день — ${itemsPerDay} точек с ТОЧНЫМИ временами (09:00, 11:30, 15:00, 18:00 — реалистичный ритм).\n2. Названия точек и адреса ТОЧНО из каталога. Между точками — конкретный транспорт из каталога с ценой и временем (например, «маршрутка из Симферополя в Ялту, 640 ₽, 1.5 ч»).\n3. У каждой точки добавь короткое \"local_tip\" — что-то полезное, не банальное (\"приходи к 9 утра, после 11 — толпа\", \"парковка за углом на ул. Х, не центральная\").\n4. 4–6 общих советов (когда ехать в этот сезон, что попробовать из еды с конкретными блюдами из каталога, чего избегать).\n5. Оцени общий бюджет на ${m.compName} (${m.days} дней) одной реальной цифрой в рублях.\n\nВерни строго JSON по схеме (без markdown-обёртки):\n{\n  \"title\": \"Краткое название маршрута\",\n  \"summary\": \"2 предложения с фишкой\",\n  \"days\": [\n    {\n      \"day\": 1,\n      \"title\": \"Тема дня\",\n      \"city\": \"Город\",\n      \"items\": [\n        { \"time\": \"09:00\", \"place\": \"Из каталога\", \"address\": \"из каталога\", \"travel\": \"транспорт из каталога с ценой\", \"local_tip\": \"короткий инсайт\", \"note\": \"что посмотреть\" }\n      ],\n      \"restaurants\": [\n        { \"name\": \"из каталога\", \"what_to_order\": \"конкретное блюдо\", \"avg_check_rub\": 1200 }\n      ]\n    }\n  ],\n  \"tips\": [\"полезный совет 1\", \"...\"],\n  \"budget_estimate_rub\": 30000\n}`;

  systemPrompt = `Ты — практичный гид по Крыму. Составляешь короткий, но НЕ банальный маршрут: с конкретными блюдами в каждом ресторане, реальными временами в пути и инсайдерскими подсказками "когда там толпа". ЖЁСТКОЕ ПРАВИЛО: места только из каталога достопримечательностей, заведения только из каталога еды, транспорт только из каталога транспорта — с реальными ценами и адресами оттуда. Никаких выдуманных мест или цен. Если в каталоге нет ресторана на этот город — пропусти ресторан, не выдумывай. Никакой воды типа "насладитесь природой" — пиши "приходи к 9, после 11 толпа". Отвечай ТОЛЬКО валидным JSON без markdown.`;

  maxTokens = 4000;
}

return [{
  json: {
    ...m,
    systemPrompt,
    userPrompt,
    maxTokens,
    catalogSize: filtered.length,
    transportCatalogSize: transportFiltered.length
  }
}];

// Парсим ответ OpenAI и рендерим красивый HTML email.
// Tier-aware: для premium показываем рестораны, план Б, чек-лист и адреса.
const openaiRaw = $input.first().json;
const content = openaiRaw.choices?.[0]?.message?.content || '{}';

let plan;
try {
  plan = JSON.parse(content);
} catch (e) {
  const m = content.match(/\{[\s\S]+\}/);
  plan = m ? JSON.parse(m[0]) : { title: 'Ошибка', summary: 'Не удалось распарсить ответ AI', days: [], tips: [], budget_estimate: '', budget_estimate_rub: 0 };
}

const meta = $('Validate & Normalize').first().json;
const isPremium = meta.tier === 'premium';

const esc = (s) => String(s ?? '').replace(/[&<>"']/g, (c) => ({ '&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;' }[c]));

// Item рендер. Поддерживает строковый формат (free) и объектный (premium).
function renderItem(item) {
  if (typeof item === 'string') {
    return `<li style="padding: 6px 0 6px 18px; position: relative;"><span style="position:absolute; left:0; color:#7A1F2B;">·</span>${esc(item)}</li>`;
  }
  const time = esc(item.time || '');
  const place = esc(item.place || '');
  const meta2 = [item.address, item.travel].filter(Boolean).map(esc).join(' · ');
  const metaLine = meta2 ? `<div style=\"font-size:13px; color:#6b6b6b; margin-top:2px;\">${meta2}</div>` : '';
  const note = item.note ? `<div style=\"font-size:14px; color:#2a2a2a; margin-top:4px;\">${esc(item.note)}</div>` : '';
  const peak = item.peak_window ? `<div style=\"font-size:12px; color:#7A1F2B; margin-top:4px;\">⏰ ${esc(item.peak_window)}</div>` : '';
  const tip = item.local_tip ? `<div style=\"font-size:13px; color:#1A2845; margin-top:4px; font-style: italic;\">💡 ${esc(item.local_tip)}</div>` : '';
  return `<li style="padding: 10px 0 10px 18px; position: relative; border-top: 1px dashed #e6e2d8;">
    <span style="position:absolute; left:0; color:#7A1F2B;">·</span>
    <strong style="font-family: Georgia, serif;">${time ? time + ' — ' : ''}${place}</strong>${metaLine}${note}${peak}${tip}
  </li>`;
}

const dayBlocks = (plan.days || []).map((d) => {
  const items = (d.items || []).map(renderItem).join('\n');
  const morningBlock = (isPremium && d.morning_strategy) ? `<p style=\"margin: 0 0 14px; padding: 10px 12px; background:#f6f3ed; border-left: 3px solid #1A2845; font-family: Georgia, serif; font-size:14px; color:#1A2845;\">${esc(d.morning_strategy)}</p>` : '';
  let extras = '';
  if (isPremium) {
    if (d.restaurants && d.restaurants.length) {
      const restList = d.restaurants.map(r => {
        const what = r.what_to_order ? `<div style=\"font-size:13px; color:#2a2a2a; margin-top:2px;\">→ ${esc(r.what_to_order)}</div>` : '';
        const checkRub = (r.avg_check_rub != null && r.avg_check_rub !== '') ? ` · ~${esc(String(r.avg_check_rub))} ₽` : (r.price ? ' · ' + esc(r.price) : '');
        const why = r.why ? `<div style=\"font-size:13px; color:#6b6b6b; margin-top:2px;\">${esc(r.why)}</div>` : '';
        const addr = r.address ? `<div style=\"font-size:12px; color:#6b6b6b; margin-top:2px;\">${esc(r.address)}</div>` : '';
        return `<li style=\"padding:8px 0; border-top: 1px dashed #e6e2d8;\"><strong>${esc(r.name)}</strong>${r.cuisine ? ' — ' + esc(r.cuisine) : ''}${checkRub}${addr}${what}${why}</li>`;
      }).join('\n');
      extras += `<div style=\"margin: 18px 0 8px;\"><div style=\"font-family: Inter, sans-serif; font-size: 11px; letter-spacing: 0.15em; text-transform: uppercase; color: #7A1F2B; margin-bottom: 8px;\">Рестораны и кафе</div><ul style=\"list-style:none; padding:0; margin:0;\">${restList}</ul></div>`;
    }
    if (d.rainy_alternative) {
      extras += `<div style=\"margin: 16px 0; padding: 12px; background: #fbf6ed; border-left: 3px solid #7A1F2B;\"><div style=\"font-family: Inter, sans-serif; font-size: 11px; letter-spacing: 0.15em; text-transform: uppercase; color: #7A1F2B; margin-bottom: 6px;\">План Б на дождь</div><div style=\"font-size:14px; color:#2a2a2a;\">${esc(d.rainy_alternative)}</div></div>`;
    }
    if (d.avoid_today && d.avoid_today.length) {
      const avoidList = d.avoid_today.map(a => `<li style=\"padding:4px 0;\">${esc(a)}</li>`).join('');
      extras += `<div style=\"margin: 16px 0; padding: 12px; background: #fdf2f0; border-left: 3px solid #7A1F2B;\"><div style=\"font-family: Inter, sans-serif; font-size: 11px; letter-spacing: 0.15em; text-transform: uppercase; color: #7A1F2B; margin-bottom: 6px;\">Не делай сегодня</div><ul style=\"margin:0; padding-left: 18px; color:#2a2a2a;\">${avoidList}</ul></div>`;
    }
    if (d.day_checklist && d.day_checklist.length) {
      const dcList = d.day_checklist.map(a => `<li style=\"padding:4px 0;\">${esc(a)}</li>`).join('');
      extras += `<div style=\"margin: 16px 0; padding: 12px; background: #f6f3ed; border-left: 3px solid #1A2845;\"><div style=\"font-family: Inter, sans-serif; font-size: 11px; letter-spacing: 0.15em; text-transform: uppercase; color: #1A2845; margin-bottom: 6px;\">Чек-лист на день</div><ul style=\"margin:0; padding-left: 18px; color:#2a2a2a;\">${dcList}</ul></div>`;
    }
    if (d.cost_breakdown_rub && typeof d.cost_breakdown_rub === 'object') {
      const c = d.cost_breakdown_rub;
      const lines = [];
      if (c.entries != null) lines.push(`входы: ${esc(String(c.entries))} ₽`);
      if (c.food != null) lines.push(`еда: ${esc(String(c.food))} ₽`);
      if (c.transport != null) lines.push(`транспорт: ${esc(String(c.transport))} ₽`);
      if (c.total != null) lines.push(`<strong>итого: ${esc(String(c.total))} ₽</strong>`);
      if (lines.length) {
        extras += `<div style=\"margin: 14px 0 0; padding: 10px 12px; background:#fff; border:1px dashed #d4c9a8; font-size:13px; color:#1A2845;\">${lines.join(' · ')}</div>`;
      }
    }
  }
  return `<div style=\"margin: 28px 0; padding: 22px; background: #fff; border: 1px solid #e6e2d8;\">
    <div style=\"display:flex; align-items:baseline; gap:14px; margin-bottom:10px;\">
      <span style=\"font-family: Georgia, serif; font-size: 28px; color: #7A1F2B; font-style: italic;\">${esc(d.day || '?')}</span>
      <h3 style=\"margin:0; font-family: Georgia, serif; font-size: 20px; color: #1A2845;\">${esc(d.title || d.city || 'День')}</h3>
    </div>
    ${morningBlock}
    <ul style=\"list-style:none; padding:0; margin:0;\">${items}</ul>
    ${extras}
  </div>`;
}).join('\n');

const tipsBlock = (plan.tips && plan.tips.length) ? `<div style=\"margin: 24px 0; padding: 18px; background: #fbf6ed;\"><div style=\"font-family: Inter, sans-serif; font-size: 11px; letter-spacing: 0.15em; text-transform: uppercase; color: #7A1F2B; margin-bottom: 10px;\">Советы</div><ul style=\"margin:0; padding-left: 20px;\">${plan.tips.map(t => `<li style=\"padding:4px 0;\">${esc(t)}</li>`).join('')}</ul></div>` : '';

const checklistBlock = (isPremium && plan.checklist && plan.checklist.length) ? `<div style=\"margin: 24px 0; padding: 18px; background: #f6f3ed; border-left: 3px solid #1A2845;\"><div style=\"font-family: Inter, sans-serif; font-size: 11px; letter-spacing: 0.15em; text-transform: uppercase; color: #1A2845; margin-bottom: 10px;\">Чек-лист в дорогу</div><ul style=\"margin:0; padding-left: 20px;\">${plan.checklist.map(t => `<li style=\"padding:4px 0;\">${esc(t)}</li>`).join('')}</ul></div>` : '';

const budgetVal = (plan.budget_estimate_rub != null && plan.budget_estimate_rub !== 0) ? (esc(String(plan.budget_estimate_rub)) + ' ₽') : (plan.budget_estimate ? esc(plan.budget_estimate) : '');
const budgetBlock = budgetVal ? `<p style=\"margin: 16px 0; font-style: italic; color: #6b6b6b;\">Общий бюджет: ${budgetVal}</p>` : '';

const tierBadge = isPremium ? `<div style=\"display:inline-block; font-family: Inter, sans-serif; font-size: 10px; letter-spacing: 0.18em; text-transform: uppercase; color: #fff; background: #7A1F2B; padding: 4px 10px; margin-bottom: 8px;\">Премиум · бесплатно в бета-периоде</div>` : '';

const html = `<!DOCTYPE html>
<html><head><meta charset=\"utf-8\"></head>
<body style=\"margin:0; padding: 0; background: #faf8f3; font-family: -apple-system, Inter, sans-serif; color: #1a1a1a; line-height: 1.5;\">
  <div style=\"max-width: 640px; margin: 0 auto; padding: 32px 24px;\">
    ${tierBadge}
    <h1 style=\"font-family: Georgia, serif; font-size: 36px; font-style: italic; color: #1A2845; margin: 0 0 10px;\">${esc(plan.title || 'Ваш маршрут по Крыму')}</h1>
    <p style=\"font-size: 16px; color: #444; margin: 0 0 6px;\">${esc(plan.summary || '')}</p>
    ${budgetBlock}
    ${dayBlocks}
    ${tipsBlock}
    ${checklistBlock}
    <hr style=\"border:none; border-top:1px solid #ddd; margin: 32px 0 18px;\">
    <p style=\"font-size: 13px; color: #888;\">План сгенерирован специально для вас — <a href=\"https://welcomecrimea.ru/\" style=\"color:#7A1F2B;\">welcomecrimea.ru</a></p>
  </div>
</body></html>`;

const subject = isPremium ? `Премиум-маршрут по Крыму на ${meta.days} дней` : `Ваш маршрут по Крыму на ${meta.days} дней`;

return [{ json: { html, subject, plan } }];
